const notFound = { error: 'not_found' }

function csvField(value) {
  const text = String(value)
  return /[",\r\n]/.test(text) ? `"${text.replaceAll('"', '""')}"` : text
}

function productToCsv(product) {
  return [
    'sku,name,price',
    [product.sku, product.name, product.price].map(csvField).join(','),
    '',
  ].join('\r\n')
}

export function createApp() {
  const app = express()
  app.disable('x-powered-by')
  app.use(express.json({ limit: '50kb' }))

  app.get('/api/health', (req, res) => {
    res.json({ ok: true })
  })

  app.get('/api/products', (req, res) => {
    res.json({ products })
  })

  app.get('/api/products/:sku.csv', (req, res) => {
    const product = products.find((p) => p.sku === req.params.sku)
    if (!product) return res.status(404).json(notFound)
    res.setHeader('Content-Type', 'text/csv')
    res.end(productToCsv(product))
  })

  app.get('/api/products/:sku', (req, res) => {
    const product = products.find((p) => p.sku === req.params.sku)
    if (!product) return res.status(404).json(notFound)
    res.json(product)
  })

  app.get('/api/categories/*path', (req, res) => {
    const path = req.params.path.join('/')
    if (!categories.includes(path)) return res.status(404).json(notFound)
    const inCategory = products.filter(
      (p) => p.category === path || p.category.startsWith(`${path}/`),
    )
    res.json({ path, products: inCategory })
  })

